void espressif_logo_draw(uint16_t *fb, size_t stride_px)
{
    if (!fb || stride_px < 480) return;

    // Fill 480x480 screen with pure white (0xFFFF in RGB565, identical byte-swapped or native)
    for (size_t y = 0; y < 480; ++y) {
        uint16_t *row = fb + y * stride_px;
        uint32_t *row32 = (uint32_t *)row;
        for (size_t x = 0; x < 240; ++x) {
            row32[x] = 0xFFFFFFFFu;
        }
    }

    // Blit the logo pixels in the center
    for (size_t r = 0; r < ESPRESSIF_LOGO_HEIGHT; ++r) {
        uint16_t *dst = fb + (ESPRESSIF_LOGO_OFFSET_Y + r) * stride_px + ESPRESSIF_LOGO_OFFSET_X;
        const uint16_t *src = &espressif_logo_pixels[r * ESPRESSIF_LOGO_WIDTH];
        memcpy(dst, src, ESPRESSIF_LOGO_WIDTH * sizeof(uint16_t));
    }
}
